from PIL import Image
import sys
def blobs(f, test, y0):
    im=Image.open(f).convert('RGB'); w,h=im.size; p=im.load()
    seen=set(); out=[]
    for y in range(y0,h):
        for x in range(w):
            if (x,y) in seen or not test(p[x,y]): continue
            st=[(x,y)]; seen.add((x,y)); pts=[]
            while st:
                a,b=st.pop(); pts.append((a,b))
                for c,d in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
                    if 0<=c<w and y0<=d<h and (c,d) not in seen and test(p[c,d]):
                        seen.add((c,d)); st.append((c,d))
            if len(pts)>20:
                xs=[q[0] for q in pts]; ys=[q[1] for q in pts]
                out.append((round(sum(xs)/len(xs),2),round(sum(ys)/len(ys),2),len(pts),min(xs),max(xs),min(ys),max(ys)))
    return out
for f in sys.argv[1:]:
    print(f,'dark',blobs(f,lambda c:sum(c)<150, 300 if '011' in f or '012' in f else 0))
    print(f,'bright',blobs(f,lambda c:min(c)>225,0))
EOF
